const l=864e5;export function dayOfYear(t){return Math.floor((new Date(t.getFullYear(),t.getMonth(),t.getDate())-new Date(t.getFullYear(),0,1))/864e5)}export function isDaylightSaving(t){const n=new Date(t.getFullYear(),0,1).getTimezoneOffset(),o=new Date(t.getFullYear(),6,1).getTimezoneOffset();return t.getTimezoneOffset()<Math.max(n,o)}export function sunTimes(t){const o=6.1+1.3*Math.cos(2*Math.PI*(dayOfYear(t)-172)/365),s=11.95+(isDaylightSaving(t)?1:0);return{sunrise:s-o,sunset:s+o}}const a=t=>{const n=Math.min(1,Math.max(0,t));return n*n*(3-2*n)};export function mix(t,n,o){const s=Math.min(1,Math.max(0,o)),c=(e,f)=>e>>f&255,u=e=>Math.round(c(t,e)+(c(n,e)-c(t,e))*s);return u(16)<<16|u(8)<<8|u(0)}export function css(t){return`#${t.toString(16).padStart(6,"0")}`}export function lightAt(t,n=null){const o=n??t.getHours()+t.getMinutes()/60,{sunrise:s,sunset:c}=sunTimes(t),u=Math.min(a((o-s+.5)/1),a((c+.5-o)/1));let e="day";return u<=0?e="night":u<1&&(e=o<12?"dawn":"dusk"),{hour:o,daylight:u,phase:e,key:`${e}:${Math.round(u*8)}`}}const r={top:726320,bottom:2764618,sun:10466559,clouds:2895940},i={top:5208499,bottom:15905402,sun:16757611,clouds:16760732},h={top:8368861,bottom:14937327,sun:16773336,clouds:16777215};export function lighting(t){const n=t.daylight,o=t.phase==="dawn"||t.phase==="dusk"?Math.sin(n*Math.PI):0,s=c=>mix(mix(r[c],h[c],n),i[c],o*.7);return{skyTop:s("top"),skyBottom:s("bottom"),sunColor:s("sun"),clouds:s("clouds"),sun:.12+1.4*n,hemi:.22+.7*n,fill:.12+.23*n,cityLights:1-n,cityNear:mix(1844019,5991293,n),cityFar:mix(2436160,8690093,n)}}
